import { useEffect } from "react";
import { useRouter } from "next/router";
import { WindowConf } from "@droid/android";
import { androidFloatWindowData } from "./data";
import { WindowConfWizard } from "./WindowConfWizard";

export function AddWindowContent(){
  const router = useRouter()

  useEffect(()=>{
    console.log('AddWindowContent: init');
    androidFloatWindowData.init();
  }, [])

  /**
   * 处理向导完成 - 添加窗口配置到列表
   */
  const handleWizardComplete = (conf: WindowConf) => {
    console.log('AddWindowContent: handleWizardComplete, adding window config:', conf.tag);
    androidFloatWindowData.data.windowData.windowList.push(conf);
    router.back();
  };

  /**
   * 处理向导取消
   */
  const handleWizardCancel = () => {
    console.log('AddWindowContent: handleWizardCancel');
    router.back();
  };

  return (
    <WindowConfWizard
      onComplete={handleWizardComplete}
      onCancel={handleWizardCancel}
    />
  )
}