import { WindowConf, WindowType } from '@droid/android';
import { useProxyWatch, useTranslation } from '@fanfanlo';
import { Alert, Box, Stack, Typography } from '@mui/material';
import {
  FloatWindowConfUI,
  DialogWindowConfUI,
  SysWindowConfUI,
} from './WindowConfUI';

export interface Step3WindowTypeProps {
  conf: WindowConf;
}

/**
 * Step 3: 窗口特定配置
 *
 * 根据 windowType 显示对应的配置组件：
 * - Float: FloatWindowConfUI
 * - Dialog: DialogWindowConfUI
 * - System: SysWindowConfUI
 */
export function Step3WindowType({ conf }: Step3WindowTypeProps) {
  const [windowType] = useProxyWatch(conf, 'windowType', conf.windowType);
  const [floatWindowConf] = useProxyWatch(conf, 'floatWindowConf', conf.floatWindowConf);
  const [dialogWindowConf] = useProxyWatch(conf, 'dialogWindowConf', conf.dialogWindowConf);
  const [systemWindowConf] = useProxyWatch(conf, 'systemWindowConf', conf.systemWindowConf);
  const { t } = useTranslation('homepage/components/android-float/window/content');

  console.log('Step3WindowType: render windowType:', windowType);

  return (
    <Stack spacing={3}>
      <Typography variant="h6">{t('Step3WindowType.title')}</Typography>

      {/* 说明文字 */}
      <Alert severity="info">
        <Typography variant="body2">
          {t('Step3WindowType.description')}
        </Typography>
      </Alert>

      {/* Float 窗口配置 */}
      {windowType === WindowType.Float && floatWindowConf && (
        <Box>
          <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: 'primary.main', mb: 2 }}>
            {t('Step3WindowType.floatConfig')}
          </Typography>
          <FloatWindowConfUI floatWindowConf={floatWindowConf} />
        </Box>
      )}

      {/* Dialog 窗口配置 */}
      {windowType === WindowType.Dialog && dialogWindowConf && (
        <Box>
          <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: 'primary.main', mb: 2 }}>
            {t('Step3WindowType.dialogConfig')}
          </Typography>
          <DialogWindowConfUI dialogWindowConf={dialogWindowConf} />
        </Box>
      )}

      {/* System 窗口配置 */}
      {windowType === WindowType.System && systemWindowConf && (
        <Box>
          <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: 'primary.main', mb: 2 }}>
            {t('Step3WindowType.systemConfig')}
          </Typography>
          <SysWindowConfUI systemWindowConf={systemWindowConf} />
        </Box>
      )}
    </Stack>
  );
}
