import { WindowConf, WindowType } from '@droid/android';
import { useProxyWatch, useTranslation } from '@fanfanlo';
import {
  Alert,
  Box,
  MenuItem,
  Select,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { RequiredLabel, OptionalLabel } from './WindowConfUI';

export interface Step1BasicInfoProps {
  conf: WindowConf;
}

/**
 * Step 1: 基本信息
 *
 * 用户输入：
 * - windowType: 窗口类型 (Float/Dialog/System)
 * - tag: 窗口标识 (必填)
 * - description: 窗口说明 (可选)
 */
export function Step1BasicInfo({ conf }: Step1BasicInfoProps) {
  const { t } = useTranslation('homepage/components/android-float/window/content');

  const [windowType] = useProxyWatch(conf, 'windowType', conf.windowType);
  const [tag] = useProxyWatch(conf, 'tag', conf.tag);
  const [description] = useProxyWatch(conf, 'description', conf.description || '');

  console.log('Step1BasicInfo: render windowType:', windowType, 'tag:', tag);

  /**
   * 获取窗口类型说明
   */
  const getWindowTypeDescription = () => {
    switch (windowType) {
      case WindowType.Float:
        return t('Step1BasicInfo.floatDesc');
      case WindowType.Dialog:
        return t('Step1BasicInfo.dialogDesc');
      case WindowType.System:
        return t('Step1BasicInfo.systemDesc');
      default:
        return '';
    }
  };

  return (
    <Stack spacing={3}>
      <Typography variant="h6">{t('Step1BasicInfo.title')}</Typography>

      {/* 说明文字 */}
      <Alert severity="info">
        <Typography variant="body2">
          {t('Step1BasicInfo.description')}
        </Typography>
      </Alert>

      {/* 窗口类型选择 */}
      <Box>
        <RequiredLabel
          label={t('Step1BasicInfo.windowTypeLabel')}
          description={t('Step1BasicInfo.windowTypeDesc')}
        />
        <Select
          value={windowType}
          onChange={(e) => {
            const newType = e.target.value as WindowType;
            console.log('Step1BasicInfo: windowType changed to', newType);
            conf.windowType = newType;
          }}
          size="small"
          fullWidth
        >
          <MenuItem value={WindowType.Float}>浮窗 (Float)</MenuItem>
          <MenuItem value={WindowType.Dialog}>对话框 (Dialog)</MenuItem>
          <MenuItem value={WindowType.System}>系统窗口 (System)</MenuItem>
        </Select>
        <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
          {getWindowTypeDescription()}
        </Typography>
      </Box>

      {/* 窗口标识 */}
      <Box>
        <RequiredLabel
          label={t('Step1BasicInfo.tagLabel')}
          description={t('Step1BasicInfo.tagDesc')}
        />
        <TextField
          value={tag}
          onChange={(e) => {
            console.log('Step1BasicInfo: tag changed to', e.target.value);
            conf.tag = e.target.value;
          }}
          placeholder={t('Step1BasicInfo.tagPlaceholder')}
          size="small"
          fullWidth
          helperText={t('Step1BasicInfo.tagHelper')}
        />
      </Box>

      {/* 窗口说明 */}
      <Box>
        <OptionalLabel
          label={t('Step1BasicInfo.descriptionLabel')}
          description={t('Step1BasicInfo.descriptionDesc')}
        />
        <TextField
          value={description}
          onChange={(e) => {
            console.log('Step1BasicInfo: description changed to', e.target.value);
            conf.description = e.target.value;
          }}
          placeholder={t('Step1BasicInfo.descriptionPlaceholder')}
          size="small"
          fullWidth
          multiline
          rows={3}
        />
      </Box>
    </Stack>
  );
}
