import { WindowConf } from '@droid/android';
import { useProxyWatch, useTranslation } from '@fanfanlo';
import { Alert, Stack, Typography } from '@mui/material';
import { HtmlConfUI } from './HtmlConfUI';

export interface Step2HtmlConfProps {
  conf: WindowConf;
}

/**
 * Step 2: HTML 内容配置
 *
 * 用户配置：
 * - htmlConf.url: 内容 URL (可选，但与 html 二选一)
 * - htmlConf.html: 内嵌 HTML 代码 (可选，但与 url 二选一)
 * - htmlConf.jsBridgeName: 注入的 JS Bridge 名称
 * - htmlConf.webViewJsName: WebView JS 类型
 * - htmlConf.javaRunnerId: Java Runner ID
 * - htmlConf.webViewJsParams: WebView JS 参数
 * - htmlConf.webViewConf: WebView 配置
 */
export function Step2HtmlConf({ conf }: Step2HtmlConfProps) {
  const [htmlConf] = useProxyWatch(conf, 'htmlConf', conf.htmlConf!);
  const { t } = useTranslation('homepage/components/android-float/window/content');
  console.log('Step2HtmlConf: render htmlConf:', htmlConf);

  if (!htmlConf) {
    return null;
  }

  return (
    <Stack spacing={3}>
      <Typography variant="h6">{t('Step2HtmlConf.title')}</Typography>

      {/* 说明文字 */}
      <Alert severity="info">
        <Typography variant="body2">
          {t('Step2HtmlConf.description')}
        </Typography>
      </Alert>

      {/* 使用 HtmlConfUI 处理所有 HtmlConf 属性 */}
      <HtmlConfUI htmlConf={htmlConf} />
    </Stack>
  );
}
